const data: WhatsNewData = {
  version: "4.14.11",
  meta: {
    title: "SoloMD {VERSION} 更新 — v4.0 – v4.11 版本说明",
    description: "SoloMD {VERSION} 版本说明。v4.11:AI/PDF 导出的畸形表格自动修复并正常渲染,新增「编号章节自动转标题」（6.2 → h2,可选开启）,应用 / CLI / MCP 三端一致。v4.8:图床（PicGo / SM.MS / S3 / GitHub）+ 体验修复（全选、删除进回收站、换行统一）。v4.7:Windows 编辑器换用原生 textarea 重写,中文输入法终于稳定。v4.6:知识图谱（类型化关系、保存视图、属性面板）+ tldraw 白板。v4.0:agent-native author 大版本 —— 内置 Agent 面板、定时 Recipe、Trace View、MCP Federation。",
  },
  breadcrumb: {
    home: "首页",
    current: "更新",
  },
  hero: {
    date: "2026 年 9 月",
    h1: "让 Agent 住进来的编辑器。",
    lead: "v4.0 是 <strong>agent-native author</strong> 大版本。Agent 从\n        \"外部 CLI 偶尔调用一下\" 变成了编辑器内的一等公民 ——\n        持续在场、跨多个 vault 工作、完整的可见性、可重放、可回滚。\n        下面所有项都在内核里,不用装插件。安装包还是 ~15 MB。",
  },
  cta: ["⬇ 下载 v{VERSION} (Mac)", "下载 (Windows)", "所有平台 →"],
  sections: [
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.11</span>\n          <time>2026 年 10 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.11 —— 一轮全面测试后的修复，其中多项关乎你的文字安全。</h2>\n        <ul>\n          <li><strong>文字更安全：</strong> 中文校对不再把文件名（文档.md、压缩包.tar.gz）和省略号当成错误，「全部修复」不会再改坏它们；UTF-16 文件按原编码保存；简繁转换不再吞掉刚输入的字；退出前最后输入的文字不再丢失（Windows、Linux）。</li>\n          <li><strong>导入 Word：</strong> 粗体留在原处，有序列表、任务列表和链接都能还原；导出 Word 时任务项带 ☐ / ☑。</li>\n          <li><strong>Linux：</strong> Ctrl+B 不再按下生效、松开撤销；不再误报「文件已被外部修改」并吞字；用过快速记录后能正常退出；粘贴图片、导出图片、文字版 PDF 里的公式都正常了；编辑菜单有了撤销和重做。</li>\n          <li><strong>快捷键：</strong> 重做（⌘⇧Z）不再同时开启专注写作；快速记录改为 Ctrl+Alt+Shift+M，Ctrl+Alt+M 重新用于公式编辑器。</li>\n          <li><strong>另外：</strong> 查找栏跟随界面语言；关闭第二个窗口会提醒保存；反向链接跳到正确的行；分栏滚动经过列表时不再错位；错误的 Mermaid 图不再把窗口顶上去；手机上的视图菜单不再被截断。</li>\n          <li><strong>安全：</strong> MCP 服务在没有 --allow-write 时不再能写入任何文件。</li>\n          <li><strong>感谢张工</strong> ——这一版的修复来自这些测试。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.10</span>\n          <time>2026 年 10 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.10 —— 编辑器里的查找回来了，Windows 文件树跟得上了。</h2>\n        <ul>\n          <li><strong>查找：</strong> 在编辑器里按 ⌘F / Ctrl+F 又能打开查找栏了——这个快捷键从 4.14.8 起失灵。</li>\n          <li><strong>Windows 文件树：</strong> 即使 Windows 传来的路径大小写不同，文件树也会跟随当前文件；同一个文件也不会再打开成两个标签页。</li>\n          <li><strong>感谢张工</strong> ——这两个修复都来自他最新的测试报告。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.9</span>\n          <time>Oct 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.9 —— Windows 重新用上完整编辑器，启动更快，菜单装下所有命令。</h2>\n        <ul>\n          <li><strong>Windows 重新使用完整编辑器：</strong> 在较新的 Windows（WebView2 154 及以上）上，我们实测微软拼音、搜狗等输入法都能正常输入。自己选过「原生」编辑器的，保持你的选择。</li>\n          <li><strong>启动更快：</strong> 启动时要做的工作减少了约一半。</li>\n          <li><strong>菜单装下所有命令：</strong> 命令面板里的每个命令都有了菜单入口——快速记录、日记、收件箱、同步与历史、大小写和中文转换。</li>\n          <li><strong>文件树：</strong> 右上角的 × 现在只是隐藏文件树，不会再把文档一起关掉（「关闭文件夹」移到了文件夹名的下拉菜单）；开启「打开文件后自动切到所在文件夹」时，也不再强行显示你隐藏的文件树。</li>\n          <li><strong>Windows：</strong> Ctrl+J 执行 AI 改写，不再打开下载页；F5 不再刷新整个应用。</li>\n          <li><strong>感谢张工</strong> ——这个版本回应的是他最新的测试报告。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.8</span>\n          <time>Oct 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.8 —— 菜单装下所有功能、工具栏收成一行，感谢张工。</h2>\n        <ul>\n          <li><strong>七个菜单：</strong> 文件、编辑、段落、格式、导航、视图、帮助——每个功能都有入口，菜单上显示你实际使用的快捷键。</li>\n          <li><strong>工具栏一行：</strong> 新建、打开、导出、插入、AI 和视图模式都是下拉菜单。</li>\n          <li><strong>「Typora / Word」快捷键预设，</strong> 以及所有人可用的新命令：提升/降低标题级别、转回段落、选中单词或整行、删除单词、恢复关闭的标签页、F8 专注、F9 打字机。</li>\n          <li><strong>Windows 实时编辑：</strong> Ctrl+Home/End、Ctrl+上/下、三击、Shift+单击都能跨段落；在代码块里选中多行不再卡死；右键菜单恢复拼写建议。</li>\n          <li><strong>另外：</strong> 分栏分隔线可拖动、公式不再被切掉底部、宽表格在 PDF 中换行、Vim 回车修复、可关闭代码块语言提示。</li>\n          <li><strong>感谢张工</strong> ——我们的测试者，这个版本的大部分改动都来自他细致的报告。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.7</span>\n          <time>Oct 2026</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.7 —— iPhone / iPad 上的文件，放在你想放的地方。</h2>\n        <ul>\n          <li><strong>工作文件夹随你选：</strong> iPhone 和 iPad 上可以把「文件」App 里的任意文件夹设为工作文件夹——iCloud 云盘、我的 iPhone 或其他 App 的文件夹，下次打开仍然记得。</li>\n          <li><strong>「文件」App 里看得到 SoloMD：</strong> 「我的 iPhone › SoloMD」现在会显示出来；从「文件」App 打开的笔记直接在原文件上编辑，保存时更新原文件而不是另存副本。</li>\n          <li><strong>触屏上重命名、移动、删除：</strong> 在文件树里长按文件，或点行尾的「⋯」。</li>\n          <li><strong>升级之后，</strong> 之前打开过的文件夹照常打开，不再提示「已经不在原来的位置」。</li>\n          <li><strong>App Store 版</strong> （iPhone、iPad、Mac）不发送任何使用统计，邀请评分只用苹果自带的评分弹窗。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.6</span>\n          <time>2026 年 10 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.6 —— 链接不再把界面占满，可以跨段落选中了。</h2>\n        <ul>\n          <li><strong>Windows 实时编辑</strong>：单击链接不再把整个 SoloMD 换成网页（之前还会导致 Esc、Alt+F4、关闭按钮全部失效）——单击是把光标放进链接，Ctrl+单击才在浏览器中打开。</li>\n          <li><strong>跨段落选中</strong>：Windows 实时编辑下可以向上或向下拖选多个段落，再加粗、删除或直接改写。跨段落的加粗、斜体、删除线、行内代码会按段分别加格式。</li>\n          <li><strong>有序列表自动重排编号</strong>：增加或删除一项后编号自动连续，所有编辑器都支持。</li>\n          <li><strong>菜单</strong>：「设置」移到「文件」菜单；「编辑」新增「查找和替换」；缩放命令收进「视图 › 缩放」；「帮助」分别列出 Markdown 速查、快捷键一览和命令行；插入菜单新增四到六级标题。</li>\n          <li><strong>另外</strong>：Windows 上开着中文输入法时按的快捷键（如 Ctrl+, 打开设置）识别得更可靠了。使用几天后，SoloMD 会问一次——只问一次——你是否愿意去 GitHub 点个 Star。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.5</span>\n          <time>2026 年 10 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.5 —— 导出不再丢东西，Mac 导出 PDF 不用打印机。</h2>\n        <ul>\n          <li><strong>导出</strong>：macOS 上「导出为 PDF（文字）」直接存成文件，不再弹打印对话框，也不需要打印机。Word 保留所有图片（网络图片、夹在文字中间的图片、表格和列表里的图片、HTML 图片）；PlantUML 流程图在 Word 和两种 PDF 里都能显示；PDF 图片版不再丢网络图片；PDF 文字版不再丢公式里的 ∫，代码不再印得发淡。</li>\n          <li><strong>Windows 实时编辑</strong>：多行段落点击时不再上下跳动；点大纲后高亮的是正确的章节。（#366、#343）</li>\n          <li><strong>键盘</strong>：文件树里 F2 重命名、Del 删除；「未保存」对话框有访问键（保存 S / 不保存 N）；设置搜索可以逐条跳转并隐藏没有结果的分类；空的第一行也能用 Ctrl+1。（#355、#357、#352、#360）</li>\n          <li><strong>文件树</strong>：拖动时提示松手会发生什么；点击导出的 .html 文件直接打开它，不再每点一次新建一篇笔记。（#361、#356）</li>\n          <li><strong>另外</strong>：Windows 编辑区右键可「复制图片」；双栏可以关闭同步（保存后预览才刷新）；选定 A4 纸张后 PDF 目录会显示页码。（#362、#347）</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.4</span>\n          <time>2026 年 9 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.4 —— 文件树随你排序，新增俄语界面。</h2>\n        <ul>\n          <li><strong>文件树排序</strong>：按名称、创建时间、修改时间排序，或者拖拽成你自己的顺序；新建的文件排在最后。（#342）</li>\n          <li><strong>设置搜索</strong>：按名称或说明筛选所有设置项，任何界面语言下都能用英文关键词搜。（#352）</li>\n          <li><strong>编辑更稳</strong>：可以选择始终显示 Markdown 符号，切换行不再跳动；可以高亮当前行。预览模式下点大纲会准确跳到标题，大纲也会跟随阅读位置。（#353、#350）</li>\n          <li><strong>Windows</strong>：编辑区右键菜单有剪切、复制、粘贴、全选；便携模式把设置存在 SoloMD.exe 旁边的 <code>data</code> 文件夹里；阅读模式有最大化按钮和笔形「切换到编辑」按钮。（#210、#295、#221）</li>\n          <li><strong>新增俄语界面</strong>，状态栏也翻译了。（#157）</li>\n          <li><strong>导出</strong>：PDF 目录页有标题和页码，所有导出改用中性配色。（#347、#332）</li>\n          <li><strong>另外</strong>：新快捷键 ⌘/Ctrl+Alt+/ 在实时编辑和仅编辑之间切换；macOS 访达按空格可预览渲染后的 Markdown；Android 能从相册插入图片了。（#180、#351、#349）</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.3</span>\n          <time>2026 年 9 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.3 —— 粘贴的图片能显示了，Windows 编辑器可以自己选。</h2>\n        <ul>\n          <li><strong>路径带空格时，粘贴的图片也能显示。</strong>像 <code>D:/Program Files/…</code> 这种带空格的文件夹，会让图片链接不符合 Markdown 语法，笔记里显示的是链接文字而不是图片。现在粘贴、拖入、上传图片都会对路径编码；旧笔记里的这类链接在预览和导出中也能显示。（#345）</li>\n          <li><strong>Windows 可以选用 CodeMirror 编辑器，不用开 Vim 模式。</strong>设置 → 写作 → 编辑器引擎。CodeMirror 有 Markdown 语法着色，实时编辑更稳；默认仍是「原生」，对中文输入法最稳妥。（#328、#344）</li>\n          <li><strong>文件树跟随当前文件。</strong>切换标签页时自动展开上层文件夹并选中文件，可在设置里关闭；文件夹里的新建输入框也和同级文件对齐了。（#333、#321）</li>\n          <li><strong>导出：</strong>独立 HTML 改为白色纸张效果；Windows 上的文字版 PDF 不再带打印日期和文件名，并可在开头加目录页（设置 → PDF）。（#332、#347）</li>\n          <li><strong>界面更清爽：</strong>⌘/Ctrl+Alt+Shift+T 隐藏工具栏按钮；没启用 AI 时不显示 AI 改写按钮；社区主题在任何内置主题下都能完整生效。（#346）</li>\n          <li>「关于」对话框里新增了对赞助者的致谢。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.2</span>\n          <time>2026 年 9 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.2 —— 导出更完整，文件树更顺手。</h2>\n        <ul>\n          <li><strong>「用系统默认程序打开」恢复可用。</strong>一条权限规则写错了位置，导致所有平台上所有「用系统程序打开」的操作都被拒绝：工具栏按钮、文档里链接的 PDF/Office 文件、词典文件夹。现在任意文件都能打开，可执行文件和脚本仍然拒绝。（#331）</li>\n          <li><strong>打印版 PDF 不再只有一页。</strong>文字版 PDF 原来只打出第一页；长表格现在每页重复表头。图片版 PDF 分页时不再切断文字或表格行。（#337）</li>\n          <li><strong>导出的 HTML 真正独立。</strong>Mermaid 图以 SVG 嵌入，不再显示源码；公式样式和字体嵌进文件，不再从 CDN 加载（打开即显示，离线也行）；本地图片也嵌入。Word 导出现在也包含 Mermaid 图。（#332、#256、#313）</li>\n          <li><strong>回车自动续列表：</strong>Windows 的「仅编辑 / 分栏」模式补上了，有序列表、任务列表、引用都支持，空项上回车结束列表。（#341）</li>\n          <li><strong>文件树：</strong>删除前先确认（仍进回收站）；文件夹图标和缩进线；选中项高亮，并决定新文件建在哪里；可选「双击展开文件夹」；⌘/Ctrl+Alt+Shift+N 在选中文件夹新建笔记；「在文件树中定位」真正滚动到文件。（#338、#340、#333）</li>\n          <li><strong>其他：</strong>Esc 关闭图片预览（#339）；输入 <code>```</code> 后提示代码块语言（#297）；Windows 文件夹选择框可以选桌面（#334）。</li>\n          <li>其中多项修复来自 <a href=\"https://github.com/chenghaitao/solomd\">@chenghaitao 的 fork</a>，感谢。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.1</span>\n          <time>2026 年 9 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.1 —— 把几个“跟你作对”的地方修掉。</h2>\n        <ul>\n          <li><strong>Windows 查找不再误删关键词。</strong>回车 / Shift+回车 在结果之间跳转，焦点一直留在搜索框，第二次回车不会再把选中的词替换成换行。输入关键词直接跳到光标后第一个结果，当前结果高亮显示，页面还在渲染时视图也会跟住它，结果被搜索框挡住时搜索框会自动让开。按 Esc 回到正文并选中结果。(#330)</li>\n          <li><strong>表格编辑器打字不再倒着出来。</strong>在单元格里输入会变成倒序（“abc” → “cba”），各平台都有。(#319)</li>\n          <li><strong>分栏窗格可以关掉了。</strong>把标签拖到编辑区会分出一个窗格，以前没有任何看得见的办法关掉它，重启后还在。现在每个窗格都有关闭按钮。(#263、#306)</li>\n          <li><strong>打开的文件一键可达。</strong>标签栏放不下时，会出现一个 ⌄ 按钮，列出所有打开的文件。(#218)</li>\n          <li><strong>文件树：</strong>新建文件 / 文件夹的输入框出现在它真正要去的位置，而不是顶部 (#321)；长文件名随侧栏宽度显示 (#259)；存放图片的附件文件夹（<code>_assets</code>、<code>*.assets</code>）默认隐藏，打开「显示隐藏文件」才显示 (#325)。</li>\n          <li><strong>表格：</strong>短单元格不会再被旁边的长列挤成竖排，应用内和 PDF / HTML / 图片导出都生效。(#271)</li>\n          <li><strong>另外：</strong>Windows 实时编辑点空白处光标会进入正文 (#326)；菜单按窗口高度显示，不再固定 360px 就滚动 (#320)；手机上展开的工具栏在屏幕内换行，竖屏也能点到设置 (#329)。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.14.0</span>\n          <time>2026 年 9 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.14.0 —— 给你天天在打的那些符号配上快捷键,而且找得到。</h2>\n        <ul>\n          <li><strong>格式化有快捷键了。</strong>加粗、斜体、删除线、行内代码、链接、一到六级标题、引用、三种列表、代码块 —— 十六个命令,全是开关:选中文字按一下加上,再按一下取消;不选中时作用于光标所在的单词。三套编辑器(包括 Windows 那一套)都支持,每一个都可以改键。(#296、#274)</li>\n          <li><strong>想用 Ctrl+B 加粗,点一下就行,但不强加给任何人。</strong>Ctrl+B 从 1.0 起就是开关文件树,所以加粗默认在 Ctrl+Shift+B。习惯 Typora 或 Word 的话,设置 → 快捷键 顶部的「写作预设」点一下就把两者对调,再点一下换回来。</li>\n          <li><strong>六十个快捷键,现在真的找得到。</strong>F1 → 快捷键 不再是一张早就过时的手写表,而是直接读取你当前生效的绑定,并且可以搜索 —— 按名称(中文或英文)或者按键本身。设置里的列表用的是同一个搜索。「插入」菜单最前面是格式命令,每一项旁边显示它的快捷键。第一次手打某种格式符号时,会有一条小提示告诉你对应的键 —— 每种只提示一次,也可以在设置里关掉。</li>\n          <li><strong>Windows:查找会跳到匹配的位置了。</strong>长文档里计数器在走、画面却不动,因为在文本框里选中文字并不会让它滚动;实时编辑模式下,匹配项可能藏在一个长代码块里、离屏幕几千像素远。两处都已修复,并在 Windows 上验证过。(#255)</li>\n          <li><strong>Windows:点进一个段落,页面不再跳。</strong>你离开的那一块会以另一个高度重新渲染,你点进去的那一块又会把自己滚进视野。现在鼠标下的那一块会留在原地;拖动选中已渲染的文字也不再把你拉进编辑状态。(#300、#240)</li>\n          <li><strong>几个小修复。</strong>Hunspell 词典选择框回到了 Hunspell 复选框下面,而不是挂在「浏览器拼写检查」下面(#246)。带行号的代码块里,空行不再让行号叠在一起(#190)。单独一行 [TOC] 会展开成目录(#289,感谢 @Zxis233)。</li>\n          <li><strong>iOS 要等后续版本。</strong>Apple 的 iOS 27 要求 SoloMD 所依赖的框架做一处改动,而那个改动还没有正式发布,所以这一版只面向 macOS、Windows、Linux 和 Android。App Store 上仍是 4.13.0,它不受影响。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.13.3</span>\n          <time>2026 年 9 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.13.3 —— 在你背后被改掉的文件,和一个按了没反应的按钮。</h2>\n        <ul>\n          <li><strong>被别的编辑器改过的文件,现在会被发现。</strong>标签页恢复的是上次关闭时的正文,而这份正文从来没有和磁盘比对过 —— 于是期间被别处改过的笔记一直显示旧版本,再打开一次也没用,因为已经打开的文件只是被切到前台。文件监听器帮不上忙:它只报告运行期间的变化,而且会刻意忽略看起来像我们自己写入的事件。现在启动时、以及每次窗口重新回到前台时,都会重新读一遍所有打开的文件。未保存的编辑绝不会被覆盖 —— 那种情况仍然走「文件已被修改」的询问,而且你点过「忽略」的那一份内容不会反复弹。(#317)</li>\n          <li><strong>右侧栏按钮总是有反应了。</strong>它翻转的是「隐藏/显示」标志,但右侧栏只有在里面某个面板真能渲染时才会画出来 —— 而多数面板需要先打开一个文件夹。没打开文件夹、或者关掉 AI 面板之后,这个按钮就只是改了个标志:第一次点看起来像死的,只有打开一次大纲才「修好」。现在它按屏幕上的实际状态判断方向,并且在打开时确保里面有东西能画。</li>\n          <li><strong>被别的软件抢走的快捷键会被点名,并给出去处。</strong>在装了 AMD 显卡驱动的机器上,七个默认的 Ctrl+Shift 组合根本到不了 SoloMD:AMD Software 把它们注册成了全局热键,按下去是驱动在响应。微软拼音还会再拿走一个。应用看不到一个从未抵达的按键,所以「设置 → 快捷键」现在会列出受影响的命令、说明各自被谁截走,并支持一键改到不冲突的键位。其他人的默认键不受任何影响,「全部恢复默认」可以还原。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.13.2</span>\n          <time>2026 年 9 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.13.2 —— Windows 上两个拨了等于没拨的写作开关。</h2>\n        <ul>\n          <li><strong>关掉 Vim 模式后,专注模式和实心光标也生效了。</strong>Windows 跑的不是同一套编辑器:从 4.7 起它用的是原生文本框,因为 WebView2 会吞掉中文输入的第一个字、还会把标点打成两个。而这两个设置都是另一套编辑器的功能,所以在 Windows 上这两个开关背后根本没有代码 ——打开 Vim 模式反而“好了”,是因为那会把另一套编辑器换回来。现在两者在 Windows 编辑器上都实现了:实时编辑下,正在写的那一块保持明亮、其余变暗;仅编辑和分栏下,当前段落之外整体变暗。实心光标是自己画上去的 —— 没有任何样式能让原生光标停止闪烁;输入法正在拼字时会把原生光标交还回去,所以打字打到一半不会找不到光标。(#316)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.13.1</span>\n          <time>2026 年 9 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.13.1 —— 一篇能执行代码的笔记，和一条吃掉文件名的工具栏。</h2>\n        <ul>\n          <li><strong>笔记不能再执行 JavaScript 了。</strong>markdown 里的内联 HTML 以前是直接渲染进应用的，既没有任何过滤，也没有内容安全策略 —— 于是别人笔记里的 <code>&lt;img src=x onerror=…&gt;</code> 会在编辑器内部执行，而那个上下文里就有应用自己的文件读写命令。代码里原本那条注释写着「这个应用只渲染用户自己的文件」，这个前提是错的，报告人证明了这一点。笔记是会流动的：共享库、下载来的文件、Git 同步的目录、AI 生成的内容。现在渲染后的 markdown 在所有显示它的地方都会过滤 —— 预览、实时编辑、演示模式和全部导出。内联 HTML 仍然可用，因为真实文档在用；脚本、事件处理器和 <code>javascript:</code> 链接不再可用。上传带脚本的 SVG 也会被拒绝，因为图床会用自己的域名把它当文档提供。<strong>如果你在旧版本里打开过来路不明的 markdown，建议更新。</strong>（#304）</li>\n          <li><strong>窗口变窄时文件名不再消失。</strong>它是整条工具栏里唯一允许收缩的元素，所以放不下时它一个人吸收了全部挤压 —— 实测只剩 8 像素宽，渲染出来就是一个被截断的字，看上去像是被挡住了。（#309、#282）</li>\n          <li><strong>展开的工具栏只有原来三分之一高。</strong>点「⋯」会撑出 195 像素 —— 在 768 高的屏幕上占掉四分之一 —— 而且第二行中间空了 378 像素，因为单行时用来把视图按钮顶到中间的占位，换行后没有东西可顶。现在是两行普通图标，一共 72 像素；桌面端点完按钮也不再自动收起，不用每次操作前都重新点开。这两条都是报告人试用第一版之后提出来的。（#282）</li>\n          <li><strong>选了暗色主题却没变化时，现在会告诉你为什么。</strong>主题市场里 15 个主题有 14 个把明暗两套配色写在一条规则里，于是装上的主题两边都赢，内置下拉框就什么也改不动了。以前没有任何地方说明这件事，而自定义 CSS 那个设置项还隔着三个分类。现在下拉框会直接写明是哪个自定义主题在接管，并给一键停用。（#282）</li>\n          <li><strong>导出文字版 PDF 时 mermaid 图能渲染了。</strong>图像导出和预览都会在渲染之后另外跑一趟把图变成图像，文字那条路一直没有，所以打印出来是图的源码。同时打印不再从 CDN 拉公式样式 —— 一个离线优先的编辑器以前每次打印都在联网，断网时公式样式还会全丢。（#301）</li>\n          <li><strong>启动更快了。</strong>以前不管文档用不用得上，所有依赖都要在第一帧之前编译完 —— 图表渲染器、两套中文词典、PDF 和 Word 导出、演示模式。现在它们等到真有东西要用才加载：启动时的代码少了一半，首屏快约 30%。机器越慢，差距越明显，而反馈正是从那些机器上来的。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.13.0</span>\n          <time>2026 年 9 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.13.0 —— 文件树终于能整理了。</h2>\n        <ul>\n          <li><strong>文件和文件夹可以直接拖着挪了。</strong>以前想把一篇笔记挪进子文件夹，只能退回 Finder / 资源管理器 —— 树里能重命名，却不能移动。现在把节点拖到文件夹上就行；键盘和手机用户在右键菜单里选「移动到…」，敲几个字母筛出文件夹、回车确认。移动可以撤销，打开着的标签页会跟着走（包括被移动文件夹<em>里面</em>的每一个），<strong>笔记里的相对链接也会重新锚定</strong> —— 搬到下一层之后 <code>_assets/图.png</code> 会自动变成 <code>../_assets/图.png</code>，不会出现「挪完图全裂了」。三位用户先后提过同一件事。（#290、#267、#273）</li>\n          <li><strong>可以显示隐藏文件了。</strong><code>.gitignore</code>、<code>.obsidian/</code>，或者整库以点开头的笔记，以前在应用里根本够不着，只能去文件管理器看。设置里新增开关，默认关 —— 大多数人不需要天天看见 <code>.git</code>。</li>\n          <li><strong>文件树可以按文件类型过滤。</strong>列出来的是你库里<strong>真实存在</strong>的扩展名和各自的数量，不是一张预设的二十种格式清单。挑了 <code>.txt</code> 之后，子树里没有 txt 的文件夹会一起收起来 —— 过滤到一半还把所有文件夹列给你、要点开才知道里面是空的，那不叫过滤。过滤生效时树顶始终有一行说明和「清除」，不会变成「我的文件不见了」。（#282）</li>\n          <li><strong>分栏时可以让编辑区和预览区不一样。</strong>并排的两栏原本是同一种底色，看久了整片连成一条宽栏。设置里打开后，预览区会拿到一个略微不同的底色；颜色是从当前主题推导出来的，八套主题各自成立，不用为每套单独调。（#279）</li>\n          <li><strong>窄窗口下的工具栏不再被悄悄切掉。</strong>1366×768 的屏幕上，工具栏需要 1532 像素，右边 166 像素连同中间的文件名一起落在窗口外 —— 它其实一直能横向滚动，只是没有任何东西告诉你这件事。现在放不下时右上角出现「⋯」，点开把整条工具栏摊成带文字标签的两三行，每个按钮都看得见，也知道它叫什么。（#282）</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.12.1</span>\n          <time>2026 年 9 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.12.1 —— 跑出版心的文字，和够不着的菜单。</h2>\n        <ul>\n          <li><strong>粘贴来的文字不会再跑出版心。</strong>从 Word、网页或聊天记录里粘出来的文本，里面的空格往往是「不换行空格」而不是普通空格 —— 有位用户提交的文件里，119 个不换行空格对 23 个普通空格。这样粘在一起的一整段，在排版引擎看来就是<strong>一个断不开的长单词</strong>，于是它直接冲出了版心：预览里要横向滚动，导出的 PDF 直接被纸边裁掉。预览、导出 PDF、打印、导出 HTML 四处一起修好。实时编辑模式一直是正常的，这也正是它看起来像渲染 bug 的原因。（#293）</li>\n          <li><strong>大纲面板重新能铺满侧栏了。</strong>在大纲和另一个面板共存时拖过中间的分隔条，再把那个面板关掉，大纲就被钉在原来的高度上 —— 一个四行高的小框待在三倍高的侧栏里，而且已经没有分隔条可拖了，因为分隔条只存在于两个面板之间。现在独占侧栏的面板会自动铺满，最下面的面板负责吸收上面剩下的空间，分隔条本身鼠标移上去也会显形，不再是一条看不见的 4 像素细线。（#294）</li>\n          <li><strong>AppImage 能被 AppImage 管理器安装了。</strong>直接双击运行一直是好的，但凡是会把它解包的工具 —— AppManager、Gear Lever —— 都会拒绝安装。打包器在里面写死了一个指向<strong>构建机器自己硬盘</strong>的绝对软链接，那个路径在任何人的电脑上都不存在。（#291）</li>\n          <li><strong>GitLab 和自建 git 远端终于有地方填地址了。</strong>选了「自定义 HTTPS Git 地址」之后，先是一个令牌输入框，然后就是一片空白：没有输入框，也没有按钮，而它上面那行提示还在让你粘贴 clone 链接。这类远端没有可供浏览的仓库列表，粘贴地址<em>就是</em>唯一的流程 —— 偏偏就是它漏了。这两类用户此前连「退出登录」也没有。</li>\n          <li><strong>斜杠命令菜单可以用键盘往下翻了。</strong>按方向键下，高亮走到第 9 项就像是停住了；用鼠标滚下去，列表又会立刻弹回顶部 —— 于是分割线以下的条目，包括白板，全都够不着。原因是弹层每按一次键就被销毁重建一次，滚动位置因此归零，而负责把高亮项滚进可视区的那段代码也从来没被执行到。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.12.0</span>\n          <time>2026 年 9 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.12.0 —— 折起来、印出来、撤回去。</h2>\n        <ul>\n          <li><strong>折叠标题，连同它下面的所有内容。</strong>点行号旁的箭头，或者用折叠命令收起当前一节、全部小节、或某一级以下的全部。折叠模型是纯文本扫描而不是 CodeMirror 的功能，所以 Windows 那套 textarea 编辑器里表现完全一致。</li>\n          <li><strong>打印不再跟着应用主题走。</strong>以前深色主题就打出深色 —— 纸上全是墨，导出的 PDF 也没法看。现在打印和 PDF 用自己的浅色配色，如果你确实想要深色，也有明确的选项。</li>\n          <li><strong>删除文件后有八秒可以撤销。</strong>做法是把删除本身推迟，而不是把文件先挪到某个巧妙的地方：在计时结束前，文件一直待在原处。任何需要文件系统先落定的操作 —— 新建、重命名、切换工作区、关窗 —— 都会先把待删除的操作执行掉再继续。</li>\n          <li><strong>随时随地快速记一笔。</strong>一个全局快捷键（默认 ⌘⌥M）在你正在做的任何事情上面弹出一个小框，输入一行、回车，它就进了收件箱，SoloMD 全程不用切到前台。</li>\n          <li><strong>任务面板。</strong>工作区里所有的 <code>- [ ]</code> 汇成一张表。优先级和截止日期两种写法都认：Obsidian Tasks 的表情符号（<code>⏫</code>、<code>📅 2026-09-10</code>）和纯 ASCII 写法（<code>!!!</code>、<code>due:2026-09-10</code>）—— 这样已有的库直接能用，也不必为了写个优先级去翻表情面板。点一条跳到那一行，勾上就写回文件。</li>\n          <li><strong>导入 Word、PDF、HTML 和表格。</strong>转换器本来就在应用里，只是没有入口。现在菜单里有了 —— 而且导入时重名不会覆盖，会自动取下一个没被占用的名字；比较是不分大小写的，因为 Windows 和 macOS 对\"什么算重名\"的看法并不一致。</li>\n          <li><strong>用表格编辑器改表。</strong>增删行列不用再数竖线。中日韩文字按显示宽度对齐，所以 Markdown 源码在等宽字体下不会每多一个汉字就歪一格。</li>\n          <li><strong>DOCX 模板。</strong>封面、目录、页眉、页码 —— 三套预设，也可以在 frontmatter 里用 <code>docx:</code> 按单篇设置。</li>\n          <li><strong>公式编号和交叉引用。</strong>行间公式上的 <code>\\label</code> 会得到编号和锚点，<code>\\eqref</code> 变成能跳过去的链接。</li>\n          <li><strong>工作区文件夹被删掉时，不再看起来像空库。</strong>如果文件夹在我们脚下消失了，文件树会用它自己的名字显示一片空 —— 和\"里面的文件全丢了\"完全分不出来。现在会明确说文件夹不见了，文件夹回来时提示也会自己消失。</li>\n          <li><strong>文件树右键菜单显示的是键名。</strong>有四个字符串从来没有在任何语言里定义过，所以菜单里显示的是 <code>explorer.copyGitUrl</code> 而不是一个标签 —— 十四种语言全都如此。现在都补上了。</li>\n          <li><strong>给 agent 用：MCP 增加 <code>list_tasks</code>。</strong>返回工作区里每一个复选框及其文件、行号和完成状态，和任务面板看到的是同一份 —— 这样 agent 和面板不会对\"该勾哪一行\"产生分歧。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.22</span>\n          <time>2026 年 9 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.22 —— 那些悄悄没反应的地方。</h2>\n        <ul>\n          <li><strong>文件 → 新建窗口，点了不开窗口。</strong>这个菜单项派发的事件从来没有监听者，所以自原生菜单上线那天起它就是死的 —— 而命令面板里的同一个操作是好的，这正是它表现为\"没有任何反应\"而不是报错的原因。现在两个入口走同一条路径，开窗失败也会明确提示，而不是默默失败。</li>\n          <li><strong>从实时编辑切到 txt，内容一片空白。</strong>Windows 上，从实时编辑模式的 Markdown 切换到 .txt 文件时，编辑区是空的，行号却还在按看不见的内容计数。内容从未丢失 —— 行号和编辑器是在不同时刻被填充的，只有行号赶上了。以前要切走再切回才能显示，现在直接就能打开。</li>\n          <li><strong>[[文件夹/笔记]] 链接会另建一个空笔记。</strong>带文件夹的 wikilink 一直解析不到，点击就在你想链接的笔记旁边新建了一个同名空文件。现在文件夹路径、frontmatter 别名、以及上次扫描之后新建的文件都能正确解析。感谢 <a href=\"https://github.com/jukejeew\">@jukejeew</a>。</li>\n          <li><strong>Linux：文件菜单里加了退出，快捷键 Ctrl+Q。</strong>平铺式窗口管理器会隐藏标题栏，既没有 ✕ 也没有明显的退出方式。同样来自 <a href=\"https://github.com/jukejeew\">@jukejeew</a>。</li>\n          <li><strong>拖动分隔条不再全屏闪烁</strong>，会导致闪烁的自定义主题在加载时也会给出提示。感谢 <a href=\"https://github.com/raopan2021\">@raopan2021</a>。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.21</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.21 —— 那个你根本看不见的快捷键页。</h2>\n        <ul>\n          <li><strong>设置 → 快捷键打开是一片空白。</strong>4.11.20 把改绑功能发了出去，设置页却是隐形的：设置面板靠一份 CSS 白名单来决定显示哪一类，新增的「快捷键」这一类漏进白名单，于是隐藏规则把它盖住、没有任何规则再把它显示回来。功能本身一直是好的，只是你看不到。白名单现在覆盖全部七个分类。</li>\n          <li><strong>下载文件可以自行校验。</strong>每个版本都会附带一份 <code>SHA256SUMS.txt</code>，覆盖该版本的所有文件，你可以核对下载到的和我们构建出来的是不是同一个。</li>\n          <li><strong>关于 Windows 上 Chrome 的「正在扫描」提示。</strong>Windows 版目前还没有代码签名，Chrome 的「增强保护」会扫描每个新版本，然后提示未检测到病毒 —— 这是通过，不是警告。另外，4.11.20 的 x64 安装包触发了 Microsoft Defender 的机器学习误报，那个下载曾短暂回退到 4.11.19。现在每个版本发布前都会先用 Defender 扫一遍，4.11.21 的 x64 安装包扫描干净，Windows x64 已经跟上最新版。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.20</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.20 —— 快捷键交给你自己定。</h2>\n        <ul>\n          <li><strong>所有应用级快捷键都能改。</strong>设置 → 快捷键里按 文件 / 编辑 / 视图 / 导航 / 工具 分组列出 37 个动作。点「更改」，按下你想要的组合键，立即生效，不用重启。也可以彻底解除绑定（想把 ⌘E、⌘D 让给别的用途，拿走就是），或单条恢复、全部恢复默认。想占用别的动作已经在用的组合键时会被拒绝，并直接告诉你是谁在用，而不是让一个键悄悄有两个主人。</li>\n          <li><strong>改了一处，处处都跟着变。</strong>你设定的组合键就是工具栏提示上写的、Markdown 速查表里列的、命令面板中显示的——以及在 macOS 上真正要紧的那一处：原生菜单栏。此前菜单是在操作系统层面占着 ⌘S 的，也就是说把「保存」改绑之后 ⌘S <em>依然</em>会保存；现在菜单会用你的组合键重建，解绑的动作则会连菜单加速键一起去掉。</li>\n          <li><strong>连编辑器里的 ⌘J 也算在内。</strong>「AI 改写」属于编辑器自己的按键表，这次同样可改绑，而且改完对已经打开的编辑器立刻生效，不用重开。只在弹窗里有意义的按键（方向键、Tab、回车、Esc）保持固定；撤销、剪切、复制、粘贴属于操作系统，也不动。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.19</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.19 —— 手机上不再是「缩小的桌面版」。</h2>\n        <ul>\n          <li><strong>为手机重做的布局。</strong>改之前在 390px 的屏幕上实测：文件树占 250px，右侧栏再占 260px——总共已经超过屏幕宽度，编辑器只剩一条缝甚至完全没有；分栏模式下两栏各约 195px；状态栏折成两行；工具栏是一条 29 个图标、要横向划着找的长带。现在两侧面板变成浮在编辑器上方的抽屉，点旁边空白即可关闭，编辑器始终占满宽度；分栏改为上下堆叠；工具栏只保留六个常用控件（文件树、保存、三种视图模式、搜索）加一个「更多」，点开后整条工具栏展开成面板，其余控件都带图标<em>和文字</em>——没有任何功能变得够不到；状态栏只留下打字时会变化的计数。设置面板也不再是 160px 导航栏挤着 145px 内容区。<strong>平板刻意不动</strong>：布局跟随视口尺寸而不是操作系统，所以 iPad 保持桌面布局，而桌面窗口拉窄后会切到手机布局。</li>\n          <li><strong>以全角标点结尾的粗体现在能正确渲染。</strong><code>**限制：**硬链接</code> 之前会原样显示星号。结束的 <code>**</code> 前面是全角冒号、后面紧接汉字，按 CommonMark 的规则这个位置的标记不能闭合——而这正是中文写作里极常见的写法。现在改为遵循 CommonMark 的 CJK 修正案，把这些判断读作「非 CJK 标点」。两个渲染引擎都改了：预览/导出用的那个，以及实时编辑背后的另一个解析器，避免同一份文档在两个面板里表现不一致。ASCII 行为不变。</li>\n          <li><strong>Windows 上多行 <code>$$</code> 公式不再被拆碎。</strong>用 <code>\\begin&#123;aligned&#125;</code> 写的公式块会被切成三段，中间缩进的那行还被渲染成灰底代码块。原因是 Windows 编辑器的分块逻辑认识 ``` 围栏却不认识 <code>$$</code>，于是一行行走进公式内部——而 <code>aligned</code> 里习惯性的四空格缩进行，就被当成了独立的缩进代码块。</li>\n          <li><strong>导出默认定位到文档所在目录。</strong>之前保存对话框只拿到一个文件名，目录沿用系统记住的「上次保存位置」——从笔记文件夹导出，对话框却可能停在上周的下载目录里。</li>\n          <li><strong>首次启动的 AI 配置里能选全部服务商，并且可以填接口地址。</strong>之前向导只列四家，而设置里有十六家，且完全没有地址输入框——用中转地址或自建服务的人只能跳过向导。现在列表与设置一致，接口地址可编辑，无需账号的本地服务也不再强制要求填 key。另外，校验不再卡在没有模型列表的服务上：网关对 <code>/v1/models</code> 返回 404 但对话完全正常时，现在改用一次 1 token 的对话来确认可用。密钥真的错了仍然会判失败。</li>\n          <li><strong>阅读模式会用你设置的字体。</strong>它此前自己声明了一套衬线字体，把字体设置整个挡掉了——代码注释里甚至写着「可以覆盖」。手机上它的退出按钮还压在第一个标题上，现在移到右下角拇指够得到的位置。</li>\n          <li><strong>macOS 安装脚本恢复可用。</strong><code>curl -fsSL https://solomd.app/install.sh | bash</code> 对所有 macOS 用户都会报 \"Failed to mount DMG\"——脚本把自己接下来要解析挂载点的那段输出给静默掉了。感谢报告者，定位非常准确。</li>\n          <li><strong>编辑状态下的代码块有了复制按钮。</strong>实时编辑模式里，围栏 ``` 是隐藏的，代码块<em>看起来</em>已经渲染好了；但手动框选复制到的仍是源码——围栏行，以及列表里的代码块每行前面那两个空格的缩进。粘进终端还得自己一行行删。现在每个代码块都带上了与预览区相同的一键复制按钮，复制出来的是渲染器眼里的内容：没有围栏，去掉代码块自身的缩进，保留代码自己的缩进。展示代码的三个地方——实时编辑器、预览区、Windows 块编辑器——都有。</li>\n          <li><strong>局域网上的 Ollama 能被检测到了。</strong>如果你把 Ollama 跑在 NAS 或另一台机器上，并把地址填进了「接口地址」，设置 → AI 却一直显示「未检测到」——探测根本没看那个字段，永远只问 localhost，尽管对话本身其实一直在正常访问你的服务。现在探测跟随你填的地址，边改边重新检测，明确告诉你探测的是哪个地址；远程机器没有响应时，提示的是该查什么（远程服务需要 <code>OLLAMA_HOST=0.0.0.0</code> 并放行端口），而不是劝你在本机装一个 Ollama。</li>\n          <li><strong>新增「OpenAI 兼容」服务商：任何你自己部署的兼容服务</strong>——llama.cpp 的 <code>llama-server</code>、LM Studio、vLLM、LocalAI 或公司内部网关。以前唯一的走法是借用别家服务商的位置，而且走不通：key 是必填的（于是大家编一个），地址只填裸的 <code>host:port</code>（恰恰是这些服务启动时打印的形式）会 404，因为代码假定你已经把 <code>/v1</code> 写进去了。现在 key 变成可选，地址会自动补全，模型列表直接从服务器读取；连不上时你看到的是服务器自己的回答（<code>HTTP 404</code>、连接被拒绝）以及该检查什么。Recipe 里也能用：<code>provider: openai-compat</code>（或 <code>llama-cpp</code> / <code>lmstudio</code> / <code>vllm</code>）。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.17</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.17 —— 找回 Option 系快捷键，以及 Linux 上少一次干等。</h2>\n        <ul>\n          <li><strong>macOS 上所有 ⌘⌥ 快捷键都能用了。</strong>macOS 会在按键送到我们手上之前，把 Option+字母 合成另一个字符——Option+N 变成 “Dead”、Option+P 变成 “π”、Option+C 变成 “ç”——而我们比对的是字母本身，于是 <kbd>⌘⌥N</kbd>（新建纯文本）、<kbd>⌘⌥P</kbd>（幻灯片）、<kbd>⌘⌥⇧P</kbd>（打印为 PDF）、<kbd>⌘⌥B</kbd>、<kbd>⌘⌥L</kbd> 在 Mac 上从来就没触发过。现在改为按物理键位匹配。顺手给<strong> <kbd>⌘⌥C</kbd> 绑上「复制为 Markdown」</strong>——这是大家真正会往别处粘的那种复制，之前偏偏没有快捷键。</li>\n          <li><strong>Linux：无障碍服务不回话时，SoloMD 不再干等它。</strong>当桌面的 AT-SPI 总线接下了请求却始终不回复，GTK 和 WebKit 会各自把界面阻塞满自己的 D-Bus 超时——25 秒和 30 秒——期间窗口画不出来、也接不了点击。现在 SoloMD 会在 GTK 初始化之前自己先问一次这条总线，预算两秒：问得到就什么都不改，读屏软件照常工作；问不到就直接以关闭无障碍的方式启动，而不是干等。在故意做成「不回包」的测试环境里，从启动到可用由 51 秒降到 3 秒。<br /><strong>这不是 Arch 和 Ubuntu 上那两个卡死报告（<a href=\"https://github.com/zhitongblog/solomd/issues/253\">#253</a>、<a href=\"https://github.com/zhitongblog/solomd/issues/200\">#200</a>）的修复。</strong>那两个永远不会自己恢复，而这里这种干等一定会自己恢复，所以是两回事，排查仍在进行中。如果你正遇到那两个问题，请到对应 issue 里跟进。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.16</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.16 —— 光标待在你放它的地方。</h2>\n        <ul>\n          <li><strong>Windows 上打字时光标不会再乱跑了。</strong>只要打开的文件被外部碰过——云盘同步、拉取更新、保存回写——SoloMD 会重新载入内容，而光标就被甩到文档另一头。有时干脆打不出字，因为同一个动作会打断正在进行的输入法组词，或者让焦点掉出编辑框——焦点一旦不在编辑器里，敲下的字母就被当成快捷键了。这个问题 4.11.1 修过，但只覆盖了 CodeMirror 编辑器，而 Windows 用的是原生文本框，一直没被修到。</li>\n          <li><strong>Gitee 同步可以用了。</strong>此前它根本无法通过认证：我们发送的是 GitHub 要求的那个用户名，而 Gitee 会直接拒绝——所以无论令牌多正确，每次都失败。现在已用真实 Gitee 仓库完整验证。(#249)</li>\n          <li><strong>允许智能体写入时，它真的能写了。</strong>「允许智能体写入笔记库」开关此前毫无作用——写入工具从未发给模型，所以它会回答自己没有这个能力。另外菜谱运行完成后停在分支上，从不出现在「待审核」里，也就无法接受或拒绝。两处均由 <a href=\"https://github.com/jclg83\">@jclg83</a> 追踪定位。(#247, #248)</li>\n          <li><strong>拼写检查支持你的语言。</strong>此前写死为英文，对其他语言使用者来说每个词都会被标红。现在可在 设置 → 写作 里选择词典，并把任意 Hunspell 的 <code>.aff</code> + <code>.dic</code> 放进按钮打开的那个文件夹。(#246)</li>\n          <li><strong>大小写转换。</strong><kbd>Shift+F3</kbd> 在 小写 / 大写 / 首字母大写 之间循环，作用于选中内容或光标所在的词；命令面板里也有独立命令。来自 Gitee 上的需求。</li>\n          <li><strong>弯引号彻底关闭。</strong>4.11.11 把它改成可选后只动了默认值，已经开着的用户依旧会在中文字体下看到撇号后一道明显的空隙。现在会为这些用户关闭一次，除非你自己再打开。(#251)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.15</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.15 —— Gitee 上说了好几周的三件事。</h2>\n        <ul>\n          <li><strong>Windows 上除了实时编辑模式，斜杠命令一直毫无反应。</strong>Windows 用的是原生文本框而不是 CodeMirror，因为 WebView2 在中文输入时会丢字——而顶替上去的那套补全，只接到了实时编辑的块编辑器上。在「仅编辑」和「分栏」模式下，弹窗从不出现、不能选择、也无法插入。受影响的还不只是斜杠菜单：<code>[[</code> 双链、<code>#</code> 标签、<code>@</code> 引用共用同一个触发机制，同样全部失效。现在四种补全在所有模式下都能用，弹窗也会跟着光标所在行走。(Gitee IK6JCC)</li>\n          <li><strong>两个 PDF 导出，现在会告诉你它们各自产出什么。</strong>「导出为 PDF」是把整页转成图片，所以里面的文字其实是一张图——不能选中、不能检索、体积还大好几倍。而大家真正想要的那个导出，就在它下面一行，名字却完全看不出区别。现在都标注清楚了：<em>PDF（文字）</em>——经系统打印，文字可选中可检索，排在前面并标为推荐；<em>PDF（图片）</em>——转成图片，但不弹对话框直接存文件。工具栏和命令面板同步。(Gitee IK8QJQ)</li>\n          <li><strong>Word / EPUB / ODT / LaTeX 导出重新和预览一致了。</strong>这几种格式走的是 Pandoc，而预览会先经过一轮容错预处理，Pandoc 拿到的却是原始文件。于是一个缩进两个空格的子列表，在屏幕上是嵌套的，导出成 .docx 就散成了平级。现在 Pandoc 看到的和你看到的是同一份文本。(Gitee IJXS8V)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.14</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.14 —— 那个把笔记吞掉的空白页。</h2>\n        <ul>\n          <li><strong>一个已经不存在的保存视图，会让整个编辑区变成空白且退不出来。</strong>报告过来时是安卓上\"笔记打不开\"——但笔记其实<em>打开了</em>：提示弹了、状态栏也数出了行数字数，然后什么都没显示。主内容区同一时间只画一样东西，而编辑器排在最后，于是一个被标记为\"打开中\"的保存视图会一直占着位置，哪怕那个视图本身早已不存在。更糟的是，那个面板的 ‹ 返回按钮就写在\"没有视图就不渲染\"的同一个块里，所以连可以点的东西都没剩下。再多打开几个文件也没用——每个文件都打开进了一个画不出来的面板里。安卓最容易碰到，因为通过系统文件选择器挑的目录常常读不到视图目录，但这个问题本身和安卓无关。现在只要视图解析不出来，编辑器立刻接管，返回按钮也保证渲染。(#245)</li>\n          <li><strong>极光主题做了一轮打磨。</strong>极光色调的细边框、面板内部改为半透明以保证在渐变背景上依然清晰，拖动面板边缘时也不会再整屏闪烁。感谢 <a href=\"https://github.com/raopan2021\">@raopan2021</a>。(#244)</li>\n          <li><strong>Arch 包重新跟上了版本。</strong><code>solomd-bin</code> 已上架 AUR，仓库内的打包配置（一直停在 4.1.0）现在跟随实际发布版本。感谢 <a href=\"https://github.com/gonwe\">@gonwe</a>。(#241)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.13</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.13 —— 像样的 Gitea 集成、11 套新主题,以及两个一直没反应的功能。</h2>\n        <ul>\n          <li><strong>Gitea / Forgejo 成为一等公民。</strong>4.11.12 让自托管同步<em>走得通</em>,这一版让它真正好用:Gitea 令牌单独存在钥匙串里,你可以同时持有 GitHub 和 Gitea 两个令牌;服务器地址会被记住,并在你正式使用前先探活;现在还能直接列出你的仓库、替你创建笔记仓库,不用再手动粘贴克隆地址。由 <a href=\"https://github.com/JumpingY\">@JumpingY</a> 贡献,已用真实 Gitea 服务端完整验证。(#150)</li>\n          <li><strong>新增 11 套社区主题。</strong>极光、深蓝、深绿、深紫、冰蓝、石墨灰、墨蓝、玫瑰粉、新拟态、VSCode Modern、暖沙 —— 由 <a href=\"https://github.com/raopan2021\">@raopan2021</a> 制作,在 设置 → 浏览社区主题 里。自定义 CSS 文件旁边也加了个重新加载按钮,在编辑器里改完主题不用重启就能看到效果。(#239)</li>\n          <li><strong>只要你收起过右侧栏,「在文件夹中搜索」就是死的。</strong>Ctrl/Cmd+Shift+F、工具栏按钮、视图菜单三个入口全都毫无反应 —— 再按一次还会把状态悄悄翻回去。搜索面板本身是渲染在右侧栏里的,而右侧栏的总隐藏开关优先级更高,于是面板被打开在了一个画不出来的地方。现在四个入口都会自动展开侧栏。(#209)</li>\n          <li><strong>Mac 上按住 Cmd 不会再误缩放整个界面了。</strong>滚轮缩放原先只要有任何一点滚动就走一档,而 Cmd 又是 ⌘S、⌘Tab 时几乎一直按着的键 —— 手指搭在触控板上的轻微漂移,就足以把整个界面一路缩到最小。现在误触触发概率降到约五分之一,刻意缩放的手感完全不变,并且在 设置 → 基础 里可以把这个手势整个关掉。(#215)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.12</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.12 —— 自托管服务器可以同步了,安卓不再展示它做不到的功能。</h2>\n        <ul>\n          <li><strong>自托管 Gitea / Forgejo 同步真的能用了。</strong>同步引擎本来就与厂商无关,卡住的是设置界面:服务商选择器只出现在保存令牌<em>之后</em>,而保存时会拿令牌去 github.com 验证、失败后直接把它删掉 —— 自托管令牌根本活不下来。现在先选服务商,非 GitHub 的令牌也不会再被拿去问 github.com。已用真实 Gitea 服务端完整验证。(#229)</li>\n          <li><strong>安卓不再显示它跑不了的同步设置。</strong>安卓版内部没有 Git 引擎,但界面照样画出整个同步面板和版本历史 —— 每个按钮都回一句莫名其妙的 <code>Command not found</code>,而且开着自动提交时<em>每次保存</em>都会报错。这些控件在安卓上已移除,改为一句明确的说明。(#230)</li>\n          <li><strong>不再在每个打开过的文件夹里生成 <code>.solomd</code>。</strong>只是打开文件夹看一眼,也会留下一个 <code>.solomd</code> 目录。这个目录是用来在多设备之间接力标签页的,所以现在只在真正的云同步目录里写入 —— 普通本地文件夹不会再产生任何东西。(#236)</li>\n          <li><strong>AI 服务商新增 OpenCode Go。</strong>一个订阅覆盖 24 个模型,由 <a href=\"https://github.com/fengzhoujingshui\">@fengzhoujingshui</a> 贡献。(#232, #235)</li>\n          <li><strong>Linux 安装脚本支持 ARM。</strong><code>install.sh</code> 此前只会去取 x86_64 的包,导致我们早已发布的 arm64 构建在树莓派、ARM 虚拟机上根本装不上。由 <a href=\"https://github.com/jysz\">@jysz</a> 修复。(#220)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.11</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.11 —— Windows 窗口按钮恢复可用,Vim 也能保存了。</h2>\n        <ul>\n          <li><strong>Windows 最小化、关闭按钮恢复可用。</strong>统一标题栏的窗口按钮因为缺了一项权限被挡住 —— 点了没反应,只能从任务栏关。已修复并在真实 Windows 构建上验证。文件菜单加回了「退出」项,下拉菜单不再因为在其下方滚动而关闭,阅读模式也有了自己的最小化/关闭按钮。(#221, #223)</li>\n          <li><strong>Vim 能保存和退出了。</strong><code>:w</code>、<code>:wq</code>、<code>:x</code>、<code>:q</code> 现在都如预期工作,走 SoloMD 真实的保存与未保存确认流程。顺带修掉了一个隐患:刚打完字就保存有可能漏掉最后几个键入。(#222)</li>\n          <li><strong>撇号后不再多出一个空格。</strong>预览默认开着智能引号,部分字体把弯撇号画成全角,看起来像多了个空格。现在引号按输入原样显示;弯引号改成新增的可选设置。(#216)</li>\n          <li><strong>安卓:词典、翻译 App 重新出现。</strong>选中文字时会列出已安装的 <code>PROCESS_TEXT</code> 应用(离线词典、翻译工具)。(#224)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.10</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.10 —— Windows 标题栏合三为一,外加三个你们催过的修复。</h2>\n        <ul>\n          <li><strong>Windows 统一标题栏。</strong>原来三行窗口 chrome 合并成一行 —— 窗口按钮、标签页、工具栏同排,和 Mac 版一致。最大化按钮上的 Snap Layouts 依然可用,MSI 安装器也换上了正式品牌样式。</li>\n          <li><strong>全选不再卡死 Windows 编辑器。</strong>块编辑器里的 Ctrl+A 改由 SoloMD 自己处理,不再和原生 textarea 抢行为。(#189, #210)</li>\n          <li><strong>代码块换行在实时编辑里生效,PDF 也不再截断代码。</strong>「代码块内自动换行」设置现在编辑时同样生效,导出 PDF 不会再切掉长代码行。(#211)</li>\n          <li><strong>有序列表里的嵌套列表不再被拍平。</strong>数字列表下的子项目符号列表保持层级。(#213)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.9</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.9 —— 缩放不再打偏,外加四个呼声很高的小功能。</h2>\n        <ul>\n          <li><strong>macOS 上 ⌘+/⌘- 缩放后点击不再错位。</strong>缩放改走系统级 webview(与 Safari 同机制),任何缩放倍率下光标都精确落在指针位置。(#192)</li>\n          <li><strong>侧栏不会再\"卡在隐藏\"。</strong>通过快捷键、设置或标签栏打开大纲(或任何面板)时,会同时唤回被自动隐藏的侧栏。(#207)</li>\n          <li><strong>命令面板说你的语言。</strong>全部 85 条命令跟随 设置 → Language(14 种语言);搜索同时匹配翻译名和英文原名。(#177)</li>\n          <li><strong>新增选项:</strong>光标不闪烁(#193)、独立代码字体(#190);<strong>从预览复制表格到邮件不再丢边框</strong>。(#189)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.8</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.8 —— 双栏对齐了,位置也记住了。</h2>\n        <ul>\n          <li><strong>分栏模式左右保持水平。</strong>编辑器和预览在任意滚动位置像素级对齐——软换行长段落、图片、HTML 块不再把两栏越拉越远,行号也始终贴住对应行。(#203)</li>\n          <li><strong>切换标签不再丢失位置。</strong>Windows 上切走再切回,画面停在你离开的地方——仅编辑、分栏、实时编辑三种模式都是。(#169)</li>\n          <li><strong><code>==高亮==</code> 在实时编辑中渲染。</strong>与加粗/斜体同款行为:光标离开即显示高亮,进入行内还原源码;代码块保持原样。打字机模式也补上了 Windows 编辑器的光标行居中。(#199)</li>\n          <li><strong>大纲跳转标签越过 az 后的错误已修复。</strong>长文档不再出现 <code>aundefined</code>。(#206)</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.7</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.7 —— Windows 只保留一条可靠的安装通道。</h2>\n        <ul>\n          <li><strong>MSI 成为唯一正式安装包。</strong>SoloMD 统一安装到 <code>C:\\Program Files\\SoloMD</code>；需要免安装时仍可使用 Portable ZIP。</li>\n          <li><strong>旧的用户级安装会安全迁移。</strong>首次从 MSI 路径启动时，SoloMD 会严格核验并移除停用的 <code>%LOCALAPPDATA%\\SoloMD</code> NSIS 安装，以及它遗留的快捷方式和任务栏固定项。</li>\n          <li><strong>文档和设置不会被删除。</strong>迁移不会触碰 <code>%APPDATA%\\app.solomd</code> 与用户文档。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.6</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.6 —— Windows 升级后继续显示正确的新图标。</h2>\n        <ul>\n          <li><strong>任务栏固定项、快捷方式与运行中的应用统一为同一个稳定身份。</strong>升级后不再回退到旧图标或空白图标。</li>\n          <li><strong>这是一个聚焦 Windows 的热修。</strong>macOS 与 Android 同步刷新安装包以保持下载一致，平台行为没有变化。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.5</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.5 —— 实时编辑终于能正确显示内嵌 HTML。</h2>\n        <ul>\n          <li><strong>块级 HTML 在编辑区直接渲染。</strong><code>&lt;div&gt;</code>、<code>&lt;table&gt;</code>、<code>&lt;details&gt;</code> 等容器在光标离开后显示实际内容。</li>\n          <li><strong>行内 HTML 像 Markdown 格式一样工作。</strong><code>&lt;strong&gt;</code>、<code>&lt;sup&gt;</code>、<code>&lt;mark&gt;</code>、<code>&lt;kbd&gt;</code> 等标签不再作为杂乱源码常驻。</li>\n          <li><strong>源码仍然随时可编辑。</strong>把光标移回 HTML 片段即可恢复原始标记。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.4</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.4 —— 新标志进入应用标题栏。</h2>\n        <ul>\n          <li><strong>标题栏换上新的 Portal 标志。</strong>应用内工具栏不再显示旧的 <code>#MD</code> 文字组合。</li>\n          <li><strong>关于弹窗同步统一。</strong>两处现在共用同一个品牌组件，以后不会再出现一处更新、另一处遗漏。</li>\n          <li><strong>macOS 文件图标已写入并注册。</strong>签名、公证后的 universal DMG 将 Markdown 文件映射到新的暖白纸张 Portal 文档图标。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.3</span>\n          <time>2026 年 8 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.3 —— 新 Logo，加上两个刚收到的修复。</h2>\n        <ul>\n          <li><strong>SoloMD 换上全新视觉标识。</strong>新的橙色 <code>#</code> Portal 应用图标已统一覆盖 macOS、Windows、Linux、iOS、Android、App Store 和官网。</li>\n          <li><strong>Markdown 文件一眼就能认出来。</strong>默认文档图标改为暖白纸张、橙色折角和同源 <code>#</code> Portal 标志。</li>\n          <li><strong>Windows Vim 模式恢复可用。</strong>开启 Vim 后立即切到 CodeMirror；普通 Windows 编辑仍保留对中文输入法更安全的 textarea 路径。</li>\n          <li><strong>代码块新增复制按钮。</strong>每个渲染后的围栏代码块右上角都有固定、可访问的一键复制操作。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.2</span>\n          <time>2026 年 7 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.2 —— 四个一直硌手的小毛病。</h2>\n        <ul>\n          <li><strong>代码块可以换行了。</strong>新设置让超宽代码折行显示而不是横向滚动条;PDF/打印始终强制换行,纸面上不再裁掉超宽代码。</li>\n          <li><strong>标签页记住你看到哪了。</strong>只滚动没点击时切走再切回,画面不再被重置到开头;行号也不再错位。</li>\n          <li><strong>Vim 的 <code>j</code>/<code>k</code> 不再跳过表格。</strong>单步移动会落在折叠的表格/公式/Mermaid 块边缘并展开源码,与方向键一致。</li>\n          <li><strong>文件树可显示完整文件名。</strong>新设置让长文件名换行完整显示,不再中段省略。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11.1</span>\n          <time>2026 年 7 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11.1 —— 光标待在你放它的地方。</h2>\n        <ul>\n          <li><strong>修复中文输入光标跳到最前面。</strong>在段落中间编辑后立刻打中文,防抖同步的竞态可能在输入法合成期间整篇替换文档——光标被甩到文档开头,打到一半的拼音也落在文首。现在合成永不被打断,外部更新也会保住光标位置。</li>\n          <li><strong>更新提示不再抢走你的浏览器。</strong>检测到新版本只显示 12 秒可点击的 toast,点了才打开;所有更新相关跳转(toast、设置检查、关于对话框)统一指向 solomd.app 官网,不再走 GitHub。</li>\n          <li><strong>AI 模型列表全量刷新</strong>,覆盖全部 14 家服务商(GPT-5.6 家族、Grok 4.5、Claude Fable 5 / Opus 4.8、Gemini 3.6、GLM-5.2、Kimi K3 等;移除已退役的 DeepSeek 旧端点)。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.11</span>\n          <time>2026 年 7 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.11 —— 坏表格自己修好。</h2>\n        <ul>\n          <li><strong>畸形表格照样渲染。</strong>AI 导出和 PDF 转 Markdown 工具经常生成与表头对不上的分隔行——多一格 <code>|---|</code>、少一格、或夹着空单元格——整个表格就静默塌成一段 <code>| … |</code> 纯文本。SoloMD 现在像 Typora / Obsidian 一样即时修复分隔行,保留每列的对齐方式;代码块里的示例表格不受影响。</li>\n          <li><strong>编号章节可自动转标题（可选开启）。</strong>公文和报告常把章节号写成纯文本——<code>6.2 出口许可证管理目录</code>——没有 <code>#</code>。新增设置（默认关闭）按层级把这类行提升为真标题:<code>6.2</code> → h2,<code>6.2.1</code> → h3。有序列表、小数开头的句子、单个数字一律不动。</li>\n          <li><strong>headless 导出与应用同引擎。</strong>CLI（<code>solomd-export</code> 新增 <code>--number-headings</code> 参数）和 MCP <code>export_note</code> 工具（新增 <code>number_headings</code> 参数）现在与应用内预览 / DOCX 导出跑完全相同的 Markdown 预处理——一套引擎,三端输出一致。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.10</span>\n          <time>2026 年 7 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.10 —— PlantUML + 预览宽度可调。</h2>\n        <ul>\n          <li><strong>PlantUML 图表（可选开启）。</strong><code>```plantuml</code> 代码块在预览和实时编辑中渲染成图表，走可配置的 PlantUML 服务器。默认关闭——不开启时笔记内容绝不出本机；填自建服务器地址即可让渲染完全留在自己的内网。</li>\n          <li><strong>预览宽度由你定。</strong>预览/阅读模式的内容栏宽度改为滑杆设置（480–1600px,原先固定 760px）。「自适应宽度」仍可一键铺满。</li>\n          <li><strong>表格不再卡光标。</strong>实时编辑里 ↑/↓ 之前会整个跳过渲染的表格,甚至掠过表格下方的整段文字。现在光标逐行移动,走到表格（以及公式 / Mermaid 块）边缘会进入源码编辑,离开后重新渲染。</li>\n          <li><strong>代码块行号修复。</strong>开行号后行距翻倍的问题修复;C 风格 <code>/** */</code> 多行注释把整块吞进第一行的问题修复;所见即所得模式现在与预览遵循同一个行号设置。</li>\n          <li><strong>点击就是点击（4.10.1）。</strong>切换标签页后立即点击编辑区——图表/图片还在渲染时——可能变成选中多行而不是放置光标。现在即使布局在点击瞬间发生位移,光标也会留在你按下的位置。</li>\n          <li><strong>点链接用默认程序打开文件（4.10.2）。</strong>Markdown 里指向本地 PDF / Office 文件的链接（<code>[报告](./report.pdf)</code>）现在用系统默认程序打开,不再转成 Markdown。新增设置（默认开启）;指向 <code>.md</code> / 文本 / 图片的链接仍在应用内打开。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.9</span>\n          <time>2026 年 7 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.9 —— 安卓真实文件夹 + 编辑器打磨。</h2>\n        <p class=\"lead\">\n          4.9 让 SoloMD 在<strong>安卓上直接打开并编辑你的真实文件夹</strong>——不是沙盒副本。\n          在 Android 11+（包括荣耀 / 华为 <strong>Magic OS</strong>，那上面\"所有文件\"权限其实什么都不给）\n          SoloMD 改用 <strong>存储访问框架（SAF）</strong>：选一次文件夹，之后就能就地读写真正的\n          <code>.md</code> 文件，通过系统内容提供程序写回。\n        </p>\n        <ul>\n          <li><strong>安卓文件夹保管库（SAF）。</strong>打开真实文件夹、就地编辑，移动端全宽布局。</li>\n          <li><strong>修复\"另存为\"。</strong>之前在安卓上会存出空文件——现在内容会正确写进你选的文件里。</li>\n          <li><strong>查找（Ctrl/⌘+F）输入即定位。</strong>边打字边跳到第一个匹配，像浏览器一样——长笔记里不再\"像是没找到\"。</li>\n          <li><strong>实时编辑方向键跨块。</strong>Windows 分块编辑器里 ↑/↓/←/→ 现在能在段落间移动光标——4.9.6 起还能识别自动换行，长段落里按 ↑ 不再整段跳过。</li>\n          <li><strong>Windows 显示行号（4.9.6）。</strong>「显示行号」设置在 Windows 编辑器里生效了，自动换行时行号依然对齐。</li>\n          <li><strong>Mermaid 图表导出 PNG（4.9.6）。</strong>点击图表 → 导出 PNG / 复制图片，2× 分辨率、背景随明暗主题。</li>\n          <li><strong>保存自动取标题（4.9.6）。</strong>未保存过的笔记若以 <code># 标题</code> 开头，保存框自动预填「标题.md」，不用再手打文件名。</li>\n          <li><strong>Linux 启动修复。</strong>AppImage 在部分 Intel / Mesa 环境不再以 <code>EGL_BAD_PARAMETER</code> 崩溃。</li>\n        </ul>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.7</span>\n          <time>2026 年 6 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.7 —— Windows 换上全新编辑器。</h2>\n        <p class=\"lead\">\n          <strong>仅限 Windows。</strong>Windows 上的 SoloMD 现在改用一套彻底重写的\n          <strong>分块编辑器</strong>,不再用 CodeMirror。WebView2 的\n          <code>contentEditable</code> 会<strong>吞掉中文 / 输入法的第一个字</strong>、\n          并<strong>把标点变成双份</strong>（搜狗最严重）—— 这个 bug 在 CodeMirror\n          里无法修复,因为它出在 WebView2 本身。新编辑器让每个块走原生\n          <code>&lt;textarea&gt;</code> 的系统输入法路径,吞字和双标点的问题不再出现。\n        </p>\n        <p>\n          新的 Windows 编辑器<strong>功能完全对齐</strong>:实时 Markdown 预览、自动补全\n          与斜杠命令（<code>/</code>）、专注模式与打字机模式、智能列表续写、AI 改写\n          （<code>Ctrl+J</code>）、文内查找替换（<code>Ctrl+F</code>）、剪贴板图片粘贴、\n          任务清单勾选、撤销 / 重做、Tab 缩进、拼写检查与自动换行。\n        </p>\n        <p style=\"opacity:.8;\">\n          <strong>macOS、Linux、iOS 和 Android 不受影响</strong> —— 继续使用现有的\n          CodeMirror 编辑器。4.7 还修复了:命令面板在悬停或滚轮滚动列表时不再乱跳（#93）。\n        </p>\n        <p class=\"version-row\" style=\"margin-top:24px;\">\n          <span class=\"version-tag\">v4.9</span>\n          <time>2026 年 7 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.9 —— Android 能打开你真正的笔记库了。</h2>\n        <p class=\"lead\">\n          此前 Android 上 SoloMD 唯一能自由读写的文件夹是\n          <code>/Android/data</code> 下的沙箱目录,未 root 的手机上任何文件管理器\n          都进不去 —— 所以你没法把 app 指向自己真正的笔记文件夹。4.9 加入\n          <strong>「所有文件访问」权限</strong>:授权一次,\n          <strong>打开文件夹</strong>就能浏览到设备上任意位置的真实库\n          （<code>Documents</code>、Syncthing / Dropbox 目录、SD 卡),\n          <strong>原地编辑</strong> —— 不再拷进沙箱。文件树、搜索、版本历史、保存\n          全部对你的真实路径生效（#148、#151）。\n        </p>\n        <p style=\"margin-top:14px;\">\n          4.9 同时修复了一批上报的 bug。\n          <strong>macOS 窗口终于能拖标题栏移动了</strong>（#153）——\n          统一标题栏上线以来,拖动调用一直被一个缺失的权限静默拒绝;\n          双击标题栏最大化也一并恢复。<strong>Android 上「文件已在磁盘上被修改」\n          弹窗不再打断输入</strong>（#148）—— Android 的文件事件会迟到数秒,\n          应用自己的保存被误判成外部修改;现在按文件修改时间判定。\n          更新提示改为打开 solomd.app 下载页（国内可达,含 Gitee 镜像),\n          不再跳 GitHub（#154);手机端隐藏了无效的「在 Finder 中显示」菜单项。\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.11</strong> —— 三个用户上报的 bug,修复。\n          <strong>Android 能正常打开文件了</strong>（#148）:从文件管理器、\n          \"打开方式\"或应用内选择器送来的文件是 <code>content://</code> URI,\n          任何文件系统调用都读不了 —— 现在会自动导入 SoloMD 文件夹\n          （保留原文件名,取不到时用文档首个标题命名）并正常打开,\n          和 iOS「文件」App 的流程一致。<strong>GitHub 同步不再\"推 main 拉\n          master\"</strong>（#147）—— 第二台设备可能永远拉不到第一台的推送;\n          现在拉取和推送用同一套分支归一逻辑,老仓库只有 master 也有回退。\n          <strong>关闭标签页回到相邻标签</strong>,不再跳到列表第一个\n          （#149 —— 根因分析来自报告者本人,感谢!）。\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.10</strong> —— 体验修复合集。Windows 实时编辑模式下\n          <strong>Ctrl+A 终于可以全选整篇文档</strong>（以前只能选中当前段落），\n          全选后复制 / 删除 / 直接输入覆盖都和普通编辑器一致。\n          <strong>删除文件 / 文件夹现在移入系统废纸篓 / 回收站</strong>，\n          不再永久删除（#112），最近文件列表支持单条移除。新增\n          <strong>“单个换行 = 换行符”</strong>设置，让预览、Windows 实时编辑和所有导出\n          （PDF、DOCX、Pandoc）对回车的理解保持一致（#141）。\n          <strong>字体和字号现在处处生效</strong> —— 实时编辑块、预览面板和阅读模式（#143）。\n          切换标签页<strong>保留光标和滚动位置</strong>（#144），关闭\"恢复标签页\"时\n          \"启动进入阅读模式\"重新生效，设置页各分类不再共享滚动位置，\n          工具栏 <strong>AI 改写按钮</strong>在 Windows 上可用了（#126）。\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.9</strong> —— iOS 文件打开,这次真修好了。从<strong>\"文件\"App</strong>、\n          隔空投送或其他 App 打开 Markdown 不再报 \"No such file or directory\"(#139)——\n          分享送进来的是一个从未解码的 <code>file://</code> 百分号编码 URL。\n          <strong>最近文件在 App 更新后不再失效</strong>(iOS 每次更新都会更换容器路径,\n          现在会自动重新定位),<strong>打开文件夹</strong>会把工作区固定到 SoloMD\n          文稿文件夹,<strong>标签栏支持手势滑动滚动</strong>。桌面端:本地\n          <strong>SVG 预览</strong>跨窗口不再丢失(#142,感谢 @beihai23)。\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.1</strong> —— 修复。<strong>查找替换</strong>重新变得好找\n          （加了命令面板入口；它一直在 Ctrl+F 后面，#137）。在 <strong>WSL</strong>\n          笔记里点击相对路径 <code>.md</code> 链接不再报 “os error 3”（#138）。把\n          <strong>阅读模式</strong>设为启动视图且关闭\"恢复标签页\"时，不再打开空白窗口\n          （#128）。<strong>macOS 应用图标</strong>改为标准圆角 squircle + 留白（#111）。\n          <strong>GitHub 同步</strong> token 失效时会主动提示重新连接，而不是甩一句原始 401。\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.8.0</strong> —— <strong>图片上传到图床</strong>。粘贴、拖入或选择图片时,\n          SoloMD 现在可以把它上传到外部图床并插入外链,而不再只复制到本地文件夹 ——\n          和 Typora / MarkText 一样。支持五种后端:<strong>PicGo</strong>(本地服务)、\n          <strong>自定义命令</strong>(PicGo-Core / uPic / 任意脚本)、<strong>SM.MS</strong>、\n          <strong>S3 兼容</strong>(阿里云 OSS / 腾讯云 COS / Cloudflare R2 / MinIO),\n          以及 <strong>GitHub 仓库 + CDN</strong>。另有\"插入网络图片 URL\"和\n          \"上传本文所有本地图片\"命令。粘贴时自动上传,图床不可达会自动回退本地副本。\n          在 设置 → 写作 中配置。\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.4</strong> —— Windows 编辑器的 <strong>Backspace / Delete</strong>\n          恢复可靠。Windows 实时编辑模式下每个段落是独立的文本框,因此在段落块开头按\n          Backspace、或在块末尾按 Delete 时会撞到文本框边界、毫无反应,删除\"时灵时不灵\"。\n          现在这两种边界按键会作用于整篇文档,像普通编辑器一样合并段落 / 删除空行,\n          光标与焦点也会跟随。\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.3</strong> —— <strong>PDF 导出</strong>不再因主题或内容使用现代\n          CSS 颜色函数（<code>color()</code>、<code>oklch()</code>、<code>color-mix()</code>）\n          而报错,导出失败也不再导致界面卡死或可缩放（#115）。另外:<strong>分屏同步滚动</strong>\n          在 Windows 上恢复正常 —— 4.7 重写 Windows 编辑器后,编辑区与预览不再互相跟随的问题已修复。\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.2</strong> —— 文件树支持<strong>拖拽调节侧边栏宽度</strong>\n          （拖边缘,180–600&nbsp;px）、<strong>按文件类型显示图标</strong>、长文件名\n          中间省略;macOS 标题栏不再与应用内工具栏重叠（#121）。另外修复 PDF 导出:\n          <strong>正文段落和列表项不再在分页处被横向切断</strong>。\n        </p>\n        <p style=\"margin-top:14px;\">\n          <strong>4.7.1</strong> —— 实时预览现在不只渲染标题,无序列表（•）、任务复选框、\n          分隔线也都渲染了(macOS / Linux / iOS / Android);源码模式恢复真·纯文本\n          (关闭实时预览时标题不再放大)。另外:文件树<strong>复制路径 / 相对路径</strong>\n          （#120）、<strong>关闭文件夹</strong>按钮（#118）、<strong>限制编辑器宽度</strong>\n          可读列宽（#109）、阅读模式也能用 Fit-Width 切换（#117）。\n        </p>",
    "<p class=\"version-row\" style=\"margin-top:8px;\">\n          <span class=\"version-tag\">v4.6</span>\n          <time>2026 年 6 月</time>\n        </p>\n        <h2 style=\"margin-top:8px;\">4.6 —— 知识图谱那一半，建好了。</h2>\n        <p class=\"lead\">\n          一次彻底的<strong>设计系统 + Vue 组件库重构</strong>（暖中性表面、橙色\n          <code>#ff9f40</code> 强调色）和<strong>统一的 macOS 标题栏</strong>\n          （红绿灯按钮内联进工具栏）—— 外加过去像 Tolaria 这类知识图谱编辑器有、\n          而 SoloMD 没有的那 7 个结构化功能。全部以纯 <code>.md</code> / YAML 落盘,\n          没有新文件格式。\n        </p>\n        <div class=\"pillars\">\n          <div class=\"pillar\">\n            <h3>属性检查器（<code>⌘⇧I</code>）</h3>\n            <p>\n              专用的 frontmatter 编辑器 —— 日期、关系、状态、标签选择器,\n              不用再手写 YAML。改动直接写回笔记的 front-matter。\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>类型驱动侧栏</h3>\n            <p>\n              <code>type:&lt;名称&gt;</code> 笔记成为侧栏一级可折叠分区\n              （types-as-lenses），每种类型可自定义图标、颜色、排序与置顶属性。\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>类型化关系</h3>\n            <p>\n              <code>belongs_to</code> / <code>related_to</code> /\n              <code>has</code> frontmatter 字段,带<strong>自动反向</strong> ——\n              声明一边,另一边自动成立。\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>关系图谱（\"Neighborhood\"）</h3>\n            <p>\n              每篇笔记的出链<em>与</em>反向关系浏览器 —— 从当前笔记出发,\n              一跳一跳走图谱。\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>保存的过滤视图</h3>\n            <p>\n              持久化的侧栏视图,存为 <code>.solomd/views/*.yml</code> ——\n              按类型 / 状态 / 日期 / 正则过滤,重启后依旧保留。\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>Inbox 工作流</h3>\n            <p>\n              <code>⌘E</code> 把当前笔记标记为已整理并自动前进到下一篇 ——\n              真正的 Inbox Zero 闭环,用来分拣随手捕获的笔记。\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>tldraw 白板</h3>\n            <p>\n              通过 <code>```tldraw</code> 围栏实现 Markdown 白板 ——\n              持久存在笔记的 <code>.md</code> 里,且与 Tolaria 的磁盘白板格式互通。\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>设计系统 UI + 统一标题栏</h3>\n            <p>\n              暖中性表面配色 + 橙色 <code>#ff9f40</code> 强调色,基于一套正式的\n              Vue 组件库重建;统一的 macOS 标题栏把红绿灯按钮内联进工具栏。\n            </p>\n          </div>\n        </div>",
    "<h2>五大支柱（v4.0）</h2>\n        <p>\n          每个都在内核里,可在设置里开关。完全兼容你已有的笔记 ——\n          没有数据库迁移、没有新文件格式、不强制云账号。\n        </p>\n        <div class=\"pillars\">\n          <div class=\"pillar\">\n            <h3>1 · 内置 Agent 面板</h3>\n            <p>\n              右侧一等公民面板,跟大纲 / 反向链接 / 标签 / 历史平级。\n              通过进程内 MCP 接口和已有 14 家 AI provider\n              组成 streamed chat-with-vault。<code>[[wikilink]]</code>\n              引用解析为真正的笔记跳转;每次 agent 调工具的卡片\n              在对话流里展开,看得到读取了什么、写入了什么。\n              回复太长?<strong>插入</strong> 和\n              <strong>复制</strong> 按钮把整段塞进当前编辑器\n              —— 有选区就替换,没选区就插到光标处。运行历史以纯\n              markdown 形式存在 <code>.solomd/agent-runs/</code>\n              下,可 grep、可被 git 追踪。\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>2 · Agent Recipe / 定时运行</h3>\n            <p>\n              声明式 agent 任务,YAML 文件放在\n              <code>&lt;workspace&gt;/.solomd/agents/*.yml</code>。\n              触发器:<code>schedule</code> (cron)、<code>on-save</code>、\n              <code>on-commit</code>、<code>on-tag-add</code>、手动。\n              <strong>安全护栏不可妥协</strong>:每次运行都开自己的\n              AutoGit 分支 <code>agent/&lt;recipe&gt;/&lt;run-id&gt;</code>,\n              所有写入只落到分支上,通过 accept / reject UI\n              评审后再合入 main;单次 <code>write-cap</code>\n              (默认 5,硬上限 50) 防止失控循环;Reject 之后分支被\n              hard-delete,git 历史里完全看不到这次运行。自带\n              <strong>11 个 Recipe 模板</strong>(周报、日志整理、\n              TODO 抽取、翻译、引用清理、CJK 校对、…) ——\n              安装、改 prompt、运行,三步走完。\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>3 · Agent Trace View</h3>\n            <p>\n              每次运行 (无论是 Panel 对话还是 Recipe) 都按步生成\n              <code>trace.jsonl</code>:\n              <code>prompt</code> / <code>model_call</code> /\n              <code>tool_call</code> / <code>tool_result</code> /\n              <code>git_commit</code> / <code>done</code>。\n              步骤卡片可展开看 args、结果、token 数、成本估算、\n              AutoGit 分支引用。<strong>从第 N 步重放</strong>\n              按钮把运行回退到第 N 步,改输入后从那里重新跑 ——\n              这是 self-correcting recipe 的入口。新增 MCP 工具\n              <code>read_agent_trace(run_id)</code>,把 trace\n              暴露给其他 agent 读取。\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>4 · 多 Vault MCP Federation</h3>\n            <p>\n              <code>solomd-mcp --workspace path1 --workspace path2 --workspace path3</code>\n              —— 一个 MCP 会话,多个 vault。工具签名加了可选\n              <code>workspace</code> 参数,默认 = 第一个传入的\n              (完全向后兼容单 vault 客户端)。AutoGit 分支按\n              workspace 隔离。<strong>设置 → 集成</strong>\n              里有 MCP profile UI:把多个 vault 命名打包,一键\n              复制 Claude Desktop 配置片段。\n            </p>\n          </div>\n          <div class=\"pillar\">\n            <h3>5 · Ollama 一等公民</h3>\n            <p>\n              我们 <strong>不</strong> 自己捆绑本地 LLM 运行时\n              —— Ollama 已经做得很好。v4.0 只是把集成磨得更顺:\n              自动检测 <code>localhost:11434</code> (设置 → AI\n              里有绿色状态灯)、未安装时一键引导安装、内置三个\n              模型预设 (<code>rewrite</code> → qwen2.5:7b ·\n              <code>quick</code> → qwen2.5:1.5b ·\n              <code>cjk</code> → qwen2.5:14b)、空模型列表时\n              内联推荐 pull。Recipe 可以 <code>provider: local</code>\n              (ollama 别名),用零云成本跑自动化循环。\n              <em>你的笔记永不离开机器</em> —— 通过 BYOK\n              Ollama 这一直是真的,v4.0 把它做成 discoverable\n              的入口。\n            </p>\n          </div>\n        </div>",
    "<h2>🛡️ 安全护栏 (别人都没做的部分)</h2>\n        <ul>\n          <li>\n            <strong>AutoGit 分支沙箱。</strong>每次 Recipe\n            运行都开自己的分支。在你点 Accept 之前,\n            <code>main</code> 一动不动。Reject 的运行\n            <em>什么也不留</em> —— 分支删除,文件树回退。\n          </li>\n          <li>\n            <strong>单次写盘上限。</strong>模型在 cap 是 5\n            的情况下要写 50 个文件,从第 6 次工具调用开始就被拒。\n            不会出现\"半成品\"状态、不会出现意外的批量改动。\n          </li>\n          <li>\n            <strong>工作区脏时拒绝启动。</strong>你有未提交的修改时\n            Recipe 触发会直接报错退出,不会把你的 WIP\n            扫进 agent 的 commit 里。\n          </li>\n          <li>\n            <strong>路径穿越加固。</strong>进程内工具接口和所有\n            接受用户传入 <code>run_id</code> / <code>path</code>\n            的 Tauri 命令,现在都会前置拒绝\n            <code>..</code> 段和绝对路径。Agent\n            从代码层就写不出 workspace。\n          </li>\n          <li>\n            <strong>可重放的 trace。</strong>每一步都按行 JSON\n            落盘。Panel 行为可疑?走 trace,定位坏步,改输入,\n            从第 N–1 步重放。\n          </li>\n        </ul>",
    "<h2>质量条</h2>\n        <ul>\n          <li>\n            <strong>首次启动向导。</strong>新装用户 60 秒内见到\n            Agent 面板 —— 引导你填 BYOK key 或装 Ollama。\n            后续可从 帮助 重新打开。\n          </li>\n          <li>\n            <strong>Recipe 菜谱(11 个起步模板)。</strong>\n            设置 → Recipes → 浏览菜谱。周报、日报、TODO 抽取、\n            翻译过一遍、引用清理、CJK 校对 agent、链接腐烂检测、\n            front-matter 规范化、大纲转博客、重构过一遍、\n            周度 tag 整理。安装、改 prompt、运行。\n          </li>\n          <li>\n            <strong>本地 REST API</strong>(只监听 localhost,\n            token 鉴权)。和 MCP 同一套接口,给那些还没接 MCP\n            的客户端用 —— Alfred / Raycast / n8n / 你自己的脚本。\n          </li>\n          <li>\n            <strong>BYOK 成本计。</strong>按 provider\n            累计已花 token 数,opt-in。设置 → 集成。\n          </li>\n          <li>\n            <strong>本地化。</strong>ja / ko 翻译骨架在 README +\n            iPad 商店元信息里。en/zh 仍是 UI 全覆盖语言。\n          </li>\n        </ul>",
    "<h2>第一天就能感受到的 UX 打磨</h2>\n        <ul>\n          <li>\n            <strong>到处的 IME 守卫。</strong>拼音用户打中文、\n            日文 kana 模式、韩文谚文 —— 按回车确认候选词不会再\n            误触发对话发送 / 文件树重命名 / 命令面板执行 / 搜索打开。\n            一次性修了 <strong>7 个输入面板</strong>。\n          </li>\n          <li>\n            <strong>Assistant 回复的 插入 / 复制 按钮。</strong>\n            每条完成的回复下方两个按钮。插入会感知当前编辑器选区\n            (有选区就替换),没选区就插到光标处。复制就是普通\n            剪贴板。\n          </li>\n          <li>\n            <strong>macOS 启动 UX。</strong>启动激活时机修对了\n            —— SoloMD 冷启动会真正到前台,不会再藏在 Finder\n            后面。窗口位置恢复时永远落在当前显示器工作区里;\n            副屏断开后从坏存档恢复时会自动重新居中,而不是开到\n            屏幕外。\n          </li>\n          <li>\n            <strong>\"生成中...\" 卡死无错误。</strong>修了。\n            provider 配错 (例如 Ollama 选了未拉取的模型) 之前会\n            让面板挂死。现在你会看到红色错误条带后端的实际响应,\n            发送按钮也会回来。\n          </li>\n        </ul>",
    "<h2>v4.0 明确不做的(以及为什么)</h2>\n        <p>说\"不\"也是产品的一部分。下面这些被认真考虑过、明确不做:</p>\n        <ul>\n          <li>\n            <strong>自带本地 LLM 运行时。</strong>Ollama 已经做得很好;\n            重新发明轮子违反\"少写需要永久维护的代码\"原则。\n            BYOK provider 仍是路径。\n          </li>\n          <li>\n            <strong>线上 Recipe 市场。</strong>服务器运维 + 内容审核 = 偏离主线。\n            菜谱直接打进发行版,跟着工具一起更新。\n          </li>\n          <li>\n            <strong>多人 / 团队 agent。</strong>违反\"一个窗口,一个写者\"。\n            这个产品给单作者用;协作属于另一个产品。\n          </li>\n          <li>\n            <strong>Copilot 风格的鬼字补全。</strong>不同的品牌定位。\n            鬼字补全会稀释作者自己的声音;我们的 agent 工作单位是 vault,\n            写入是批量 + 可审 + 走分支的。\n          </li>\n        </ul>",
    "<h2>升级须知</h2>\n        <ul>\n          <li>\n            <strong>没有文件格式变更。</strong>已有的 <code>.md</code>、\n            AutoGit 历史、同步配置、BYOK key 全部原样保留。\n          </li>\n          <li>\n            <strong>Agent 面板首次启动自动开。</strong>v3.6.x\n            用户因为 v4-beta 期间脚手架的默认值,会有一个隐藏的\n            <code>showAgentPanel: false</code>;一次性迁移会把它\n            翻成 true,你才会真正看到这个主打功能。不想要可以\n            <code>⌘⇧P → View: Toggle Agent Panel</code> 关掉。\n          </li>\n          <li>\n            <strong>设置面板新增 <em>Recipes</em> 和 <em>成本计</em>\n            两个分页</strong>,在 <em>集成</em> 下。已有的设置位置不变。\n          </li>\n          <li>\n            <strong>MCP server (<code>solomd-mcp</code>) 加了\n            <code>--workspace</code> 参数</strong>(可重复)。\n            原来单 workspace 的 MCP 客户端继续工作不受影响;\n            federation 行为是可选加入的。\n          </li>\n        </ul>",
    "<h2>🔮 接下来</h2>\n        <p>\n          5 大支柱 + 质量条是这次的主要内容。<em>v4.x\n          及之后</em> 的开放方向都在\n          <a href=\"https://github.com/zhitongblog/solomd/blob/main/docs/roadmap.md\">roadmap</a>\n          上:沙盒化的脚本 API、CLI v2 (终端里 rewrite / commit /\n          语义搜索 / 触发 recipe)、以及一直拖着的\n          <em>\"SoloMD 要不要做成商业产品?\"</em> 问题\n          (付费同步 —— v3.0 时代的老问题,还没答,\n          没决定之前不会动这块的工程)。\n        </p>",
  ],
  thanks: "感谢所有在静默期内提交 issue / 发 PR / 用真实 vault\n        跑 v4-beta build 的人。v4.0 能 ship 是因为 dogfood\n        把集成测试漏掉的 bug 一个个揪出来了。\n        早期版本:<a href=\"/zh/blog/\">看博客 →</a>",
};

export default data;
